#include "CombatEditorPanel.h"
#include "EditorPanels.h"
#include <imgui.h>
#include <imgui_stdlib.h>
#include <algorithm>
#include <cmath>
#include <filesystem>
void CombatEditorPanel::New(const std::string&root){m_asset={};m_asset.header.id=engine::AssetHandle::Generate();m_asset.name="NewCombatProfile";m_asset.damageTypes.push_back({});m_asset.combo.push_back({});m_path=(std::filesystem::path(root)/"GameAssets"/"Combat"/"NewCombatProfile.3dgcombat").string();m_selectedStep=0;m_dirty=true;m_status.clear();}
bool CombatEditorPanel::SaveForShutdown(const std::string&root,std::string*error){if(m_path.empty())New(root);if(!engine::SaveCombatAsset(m_path,m_asset,error))return false;m_dirty=false;return true;}
bool CombatEditorPanel::AssetCombo(const char*label,EditorAssets::Type type,std::string&path,engine::AssetHandle&id,EditorAssets&assets){bool changed=false;const auto preview=path.empty()?std::string("None"):std::filesystem::path(path).filename().string();if(ImGui::BeginCombo(label,preview.c_str())){if(ImGui::Selectable("None",path.empty())){path.clear();id={};changed=true;}for(const auto&p:assets.ContentAssetPaths(type)){ImGui::PushID(p.c_str());const auto name=std::filesystem::path(p).filename().string();if(ImGui::Selectable(name.c_str(),p==path)){path=p;id=assets.AssetIdForPath(p);changed=true;}ImGui::PopID();}ImGui::EndCombo();}return changed;}
void CombatEditorPanel::DrawTimeline(){const ImVec2 size(ImGui::GetContentRegionAvail().x,100);ImGui::InvisibleButton("CombatTimeline",size);auto*d=ImGui::GetWindowDrawList();const auto a=ImGui::GetItemRectMin(),b=ImGui::GetItemRectMax();d->AddRectFilled(a,b,IM_COL32(16,19,25,255));float total=0;for(const auto&s:m_asset.combo)total+=s.duration;total=std::max(total,.001f);float x=a.x,offset=0;for(std::size_t i=0;i<m_asset.combo.size();++i){const auto&s=m_asset.combo[i];const float w=size.x*s.duration/total;d->AddRectFilled({x,a.y+22},{x+w,b.y-12},i==static_cast<std::size_t>(m_selectedStep)?IM_COL32(145,70,52,255):IM_COL32(54,80,112,255));d->AddText({x+5,a.y+27},IM_COL32_WHITE,s.name.c_str());const float hit=x+w*s.hitTime/s.duration;d->AddLine({hit,a.y+16},{hit,b.y-8},IM_COL32(255,80,65,255),2);const float ws=x+w*s.inputWindowStart/s.duration,we=x+w*s.inputWindowEnd/s.duration;d->AddLine({ws,b.y-17},{we,b.y-17},IM_COL32(90,230,130,255),5);x+=w;offset+=s.duration;}const float play=a.x+size.x*std::clamp(m_previewTime/total,0.f,1.f);d->AddLine({play,a.y},{play,b.y},IM_COL32_WHITE,2);}
CombatEditorPanel::Result CombatEditorPanel::Draw(EditorAssets&assets,const std::string&root,bool*open){Result result;if(!m_asset.header.id.Valid())New(root);if(!m_pendingOpen.empty()){std::string e;if(engine::LoadCombatAsset(m_pendingOpen,&m_asset,&e)){m_path=m_pendingOpen;m_dirty=false;m_selectedStep=0;}else m_status=e;m_pendingOpen.clear();}if(!ImGui::Begin(EditorPanels::Name(EditorPanels::Panel::CombatEditor),open)){ImGui::End();return result;}if(ImGui::Button("New"))New(root);ImGui::SameLine();if(ImGui::Button("Save")){std::string e;if(engine::SaveCombatAsset(m_path,m_asset,&e)){m_dirty=false;result.saved=true;result.message="Saved combat profile: "+m_path;}else result.message=e;}ImGui::SameLine();if(ImGui::Button("Apply to Selected"))result.applySelected=true;ImGui::SameLine();ImGui::TextUnformatted(m_path.c_str());m_dirty|=ImGui::InputText("Profile Name",&m_asset.name);
    if(ImGui::BeginTabBar("CombatTabs")){if(ImGui::BeginTabItem("Defense and Targeting")){m_dirty|=ImGui::DragInt("Team (0 = neutral)",&m_asset.team,1,0,32);m_dirty|=ImGui::Checkbox("Friendly Fire",&m_asset.friendlyFire);m_dirty|=ImGui::DragFloat("Poise",&m_asset.poise,.5f,0,100000);m_dirty|=ImGui::DragFloat("Stagger Recovery",&m_asset.staggerRecovery,.02f,0,60,"%.2f s");m_dirty|=ImGui::SliderFloat("Block Reduction",&m_asset.blockReduction,0,1,"%.0f%%");m_dirty|=ImGui::DragFloat("Block Stamina Cost",&m_asset.blockStaminaCost,.25f,0,100000);m_dirty|=ImGui::DragFloat("Parry Window",&m_asset.parryWindow,.01f,0,5,"%.3f s");m_dirty|=ImGui::DragFloat("Immunity After Hit",&m_asset.immunityAfterHit,.01f,0,10,"%.3f s");m_dirty|=ImGui::DragFloat("Targeting Range",&m_asset.targetingRange,.1f,0,100000,"%.2f m");m_dirty|=ImGui::Checkbox("Auto-face Target",&m_asset.autoFaceTarget);ImGui::EndTabItem();}
        if(ImGui::BeginTabItem("Damage Types")){for(std::size_t i=0;i<m_asset.damageTypes.size();++i){auto&t=m_asset.damageTypes[i];ImGui::PushID(static_cast<int>(i));m_dirty|=ImGui::InputText("Name",&t.name);m_dirty|=ImGui::DragFloat("Damage Multiplier",&t.damageMultiplier,.01f,0,100);m_dirty|=ImGui::DragFloat("Stagger Multiplier",&t.staggerMultiplier,.01f,0,100);m_dirty|=ImGui::SliderFloat("Armor Penetration",&t.armorPenetration,0,1);if(ImGui::Button("Remove Type")&&m_asset.damageTypes.size()>1){m_asset.damageTypes.erase(m_asset.damageTypes.begin()+static_cast<std::ptrdiff_t>(i));m_dirty=true;ImGui::PopID();break;}ImGui::Separator();ImGui::PopID();}if(ImGui::Button("Add Damage Type")){m_asset.damageTypes.push_back({"DamageType",1,1,0});m_dirty=true;}ImGui::SeparatorText("Resistances");for(std::size_t i=0;i<m_asset.resistances.size();++i){auto&r=m_asset.resistances[i];ImGui::PushID(static_cast<int>(i));if(ImGui::BeginCombo("Damage Type",r.damageType.c_str())){for(const auto&t:m_asset.damageTypes)if(ImGui::Selectable(t.name.c_str(),r.damageType==t.name)){r.damageType=t.name;m_dirty=true;}ImGui::EndCombo();}m_dirty|=ImGui::DragFloat("Incoming Multiplier",&r.multiplier,.01f,0,10);if(ImGui::Button("Remove Resistance")){m_asset.resistances.erase(m_asset.resistances.begin()+static_cast<std::ptrdiff_t>(i));m_dirty=true;ImGui::PopID();break;}ImGui::PopID();}if(ImGui::Button("Add Resistance")){m_asset.resistances.push_back({m_asset.damageTypes.front().name,1});m_dirty=true;}ImGui::EndTabItem();}
        if(ImGui::BeginTabItem("Combo")){DrawTimeline();float duration=0;for(const auto&s:m_asset.combo)duration+=s.duration;if(m_playing)m_previewTime=std::fmod(m_previewTime+ImGui::GetIO().DeltaTime,std::max(duration,.001f));if(ImGui::Button(m_playing?"Pause":"Play"))m_playing=!m_playing;ImGui::SameLine();ImGui::SliderFloat("Preview Time",&m_previewTime,0,std::max(duration,.001f));for(std::size_t i=0;i<m_asset.combo.size();++i){ImGui::PushID(static_cast<int>(i));if(ImGui::Selectable(m_asset.combo[i].name.c_str(),m_selectedStep==static_cast<int>(i)))m_selectedStep=static_cast<int>(i);ImGui::PopID();}if(ImGui::Button("Add Step")){m_asset.combo.push_back({"Attack"+std::to_string(m_asset.combo.size()+1)});m_selectedStep=static_cast<int>(m_asset.combo.size()-1);m_dirty=true;}ImGui::SameLine();if(ImGui::Button("Remove Step")&&m_asset.combo.size()>1){m_asset.combo.erase(m_asset.combo.begin()+m_selectedStep);m_selectedStep=std::max(0,m_selectedStep-1);m_dirty=true;}m_selectedStep=std::clamp(m_selectedStep,0,static_cast<int>(m_asset.combo.size()-1));auto&s=m_asset.combo[static_cast<std::size_t>(m_selectedStep)];ImGui::PushID("ComboStep");m_dirty|=ImGui::InputText("Step Name",&s.name);m_dirty|=AssetCombo("Action Clip",EditorAssets::Type::AnimationClip,s.actionClipPath,s.actionClipId,assets);if(ImGui::BeginCombo("Damage Type",s.damageType.c_str())){for(const auto&t:m_asset.damageTypes)if(ImGui::Selectable(t.name.c_str(),s.damageType==t.name)){s.damageType=t.name;m_dirty=true;}ImGui::EndCombo();}m_dirty|=ImGui::DragFloat("Damage",&s.damage,.25f,0,100000);m_dirty|=ImGui::DragFloat("Stamina Cost",&s.staminaCost,.25f,0,100000);m_dirty|=ImGui::DragFloat("Duration",&s.duration,.01f,.001f,60);m_dirty|=ImGui::DragFloat("Hit Time",&s.hitTime,.01f,0,s.duration);m_dirty|=ImGui::DragFloat("Input Window Start",&s.inputWindowStart,.01f,0,s.duration);m_dirty|=ImGui::DragFloat("Input Window End",&s.inputWindowEnd,.01f,0,s.duration);m_dirty|=ImGui::DragFloat("Range",&s.range,.05f,0,10000);m_dirty|=ImGui::DragFloat("Trace Radius",&s.radius,.02f,0,1000);m_dirty|=ImGui::InputText("Hit Reaction",&s.hitReaction);m_dirty|=AssetCombo("Hit Particle",EditorAssets::Type::Particle,s.particlePath,s.particleId,assets);m_dirty|=AssetCombo("Hit Audio",EditorAssets::Type::Audio,s.audioPath,s.audioId,assets);ImGui::PopID();ImGui::EndTabItem();}
        if(ImGui::BeginTabItem("Live Debug")){ImGui::DragFloat("Target Health",&m_debugHealth,.5f,0,100000);ImGui::Checkbox("Target Blocking",&m_debugBlocking);ImGui::DragFloat("Accumulated Stagger",&m_debugPoise,.5f,0,std::max(m_asset.poise,1.f));if(ImGui::Button("Simulate Current Hit")){const auto&s=m_asset.combo[static_cast<std::size_t>(std::clamp(m_selectedStep,0,static_cast<int>(m_asset.combo.size()-1)))];float damage=s.damage;for(const auto&t:m_asset.damageTypes)if(t.name==s.damageType){damage*=t.damageMultiplier;m_debugPoise+=s.damage*t.staggerMultiplier;}if(m_debugBlocking)damage*=1-m_asset.blockReduction;m_debugHealth=std::max(0.f,m_debugHealth-damage);m_status=m_debugBlocking?"Blocked hit simulated.":"Hit simulated.";if(m_debugPoise>=m_asset.poise&&m_asset.poise>0){m_debugPoise=0;m_status="Stagger triggered.";}}ImGui::ProgressBar(m_debugHealth/100.f,{0,0},"Health");ImGui::ProgressBar(m_asset.poise>0?m_debugPoise/m_asset.poise:0,{0,0},"Stagger");ImGui::EndTabItem();}ImGui::EndTabBar();}
    engine::NormalizeCombatAsset(m_asset);std::string validation;if(!engine::ValidateCombatAsset(m_asset,&validation))ImGui::TextColored({1,.35f,.25f,1},"%s",validation.c_str());else ImGui::TextColored({.35f,1,.55f,1},"Combat profile is valid.");if(m_dirty)ImGui::TextColored({1,.7f,.2f,1},"Unsaved changes");if(!m_status.empty())ImGui::TextWrapped("%s",m_status.c_str());ImGui::End();return result;}
